    classname AS `report.rows.group`,
    totalamount AS `report.rows.coldata[1].value`,
    percentofincome AS `report.rows.coldata[2].value`,
    columntitle AS `report.columns.coltitle`,
    columntype AS `report.columns.coltype`,
    clientid,
    organisationid,
    reportgenerateddate,
    accountingmethod,
    summarizecolumnsby,
    reportbasis,
    etlinserttime,
    etlupdatetime
FROM c{clientID}_qbo_classsales;

-- DepartmentSales View
DROP VIEW IF EXISTS {etani_client_id}_qbo_departmentsales;
CREATE VIEW {etani_client_id}_qbo_departmentsales AS
SELECT
    clientid,
    organisationid,
    reportname AS `report.header.reportname`,
    startperiod AS `report.header.startperiod`,
    endperiod AS `report.header.endperiod`,
    currency AS `report.header.currency`,
    rowgroup AS `row.group`,
    department AS `row.coldata[0].value`,
    total_amount AS `row.coldata[1].value`,
    total_amount_id AS `row.coldata[1].id`,
    percent_of_total_income AS `row.coldata[2].value`,
    column1_title AS `columns[0].coltitle`,
    column2_title AS `columns[1].coltitle`,
    column3_title AS `columns[2].coltitle`,
    column1_type AS `columns[0].coltype`,
    column2_type AS `columns[1].coltype`,
    column3_type AS `columns[2].coltype`,
    row_type AS `row.type`,
    reportdate,
    generatedtime,
    etlinserttime,
    etlupdatetime
FROM c{clientID}_qbo_departmentsales;